{
  "appearance_facts": [
    {
      "location": "line plot, x-axis 2005 to 2015, y-axis 0 to ~24",
      "fact": "A single blue line with black circular markers descends monotonically from the top-left to the bottom-right across the plot area."
    },
    {
      "location": "top-left, near x=2005, y≈24",
      "fact": "The first data point is the highest on the chart, with a label above it."
    },
    {
      "location": "bottom-right, near x=2015, y≈10",
      "fact": "The last data point is the lowest on the chart, with a label above it."
    },
    {
      "location": "middle segment, x=2009 to x=2010",
      "fact": "The steepest single-year drop appears between 2009 and 2010."
    },
    {
      "location": "middle segment, x=2010 to x=2012",
      "fact": "The line flattens noticeably, showing smaller year-over-year decreases."
    },
    {
      "location": "right segment, x=2013 to x=2015",
      "fact": "The decline resumes and steepens again toward the final point."
    },
    {
      "location": "entire series",
      "fact": "No point rises above the previous point; the trend is strictly downward."
    }
  ],
  "printed_facts": [
    {
      "location": "title, top-left",
      "fact": "Chart title reads 'Global Temperature Change'."
    },
    {
      "location": "y-axis label, left",
      "fact": "Axis label reads 'Temperature (°C)'."
    },
    {
      "location": "x-axis label, bottom",
      "fact": "Axis label reads 'Year'."
    },
    {
      "location": "y-axis ticks",
      "fact": "Visible numeric ticks are 0, 5, 10, 15, 20."
    },
    {
      "location": "x-axis ticks",
      "fact": "Year ticks run 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015."
    },
    {
      "location": "point annotation, 2005",
      "fact": "Label '$24.0°C' above the first marker."
    },
    {
      "location": "point annotation, 2006",
      "fact": "Label '$22.8°C' above the marker."
    },
    {
      "location": "point annotation, 2007",
      "fact": "Label '$21.9°C' above the marker."
    }
  ],
  "public_definitions": [
    "Routing criterion: 'Magnitude of change across the review period' (readonly companion field).",
    "Record workflow: 'Substantial trend follow-up' (readonly companion field).",
    "Review scope: 'Multi-year environmental trend' (readonly companion field).",
    "Program area: 'Temperature monitoring' (readonly companion field).",
    "Option: 'Escalate the 2005-2015 temperature decline for follow-up'.",
    "Option: 'Keep the 2005-2015 temperature decline on routine monitoring'.",
    "Option: 'Archive the temperature trend record without targeted follow-up'."
  ],
  "uncertain": [
    "The point labels include a leading '$' symbol before the °C values (e.g., '$24.0°C'), which is inconsistent with a temperature unit; the intended numeric values are read as the digits shown.",
    "No explicit threshold value defining 'substantial' change is provided in the policy tables or instructions, so the magnitude must be judged from the charted values alone.",
    "The 2011 marker is present on the line but has no visible numeric label above it."
  ]
}
